import React, { useState, useRef, useEffect, useContext, useCallback, memo } from "react";
import styled, { keyframes } from "styled-components";

import fetchQuery from "../components/fetchQuery";
import PageWrapper from "../components/PageWrapper";
import BookCard from "../components/BookCard";
import CardButton from "../components/CardButton";
import BookGrid from "../components/BookGrid";

import withLoadingAnimation from "../components/hoc/withLoadingAnimation";
import withImageLoading from "../components/hoc/withImageLoading";

import { ThemeContext } from "../components/ThemeContext";

const shine = keyframes`
  0% { background-position: -200px 0; }
  100% { background-position: 200px 0; }
`;

const Container = styled.div`
  margin: 40px auto;
  max-width: 1400px;
  font-family: "Poppins", sans-serif;
  display: flex;
  flex-direction: column;
  gap: 30px;
`;

const Heading = styled.h2`
  font-size: 3rem;
  font-weight: 800;
  background: linear-gradient(90deg, #ff416c, #ff4b2b, #ffe259);
  background-size: 200% auto;
  color: transparent;
  -webkit-background-clip: text;
  background-clip: text;
  animation: ${shine} 3s linear infinite;
  text-align: center;
`;

const SearchWrapper = styled.form`
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 15px;
  justify-content: center;
  margin-bottom: 20px;
`;

const DropDownWrapper = styled.div`
  position: relative;
`;

const DropDownButton = styled.button`
  padding: 10px 18px;
  background: #1f1f1f;
  color: white;
  border: none;
  border-radius: 12px;
  font-size: 16px;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 5px;
  transition: all 0.3s ease;
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.3);

  &:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 25px rgba(0, 0, 0, 0.4);
  }
`;

const DropDownContent = styled.div`
  position: absolute;
  top: 45px;
  left: 0;
  background: #1f1f1f;
  color: #fff;
  border-radius: 10px;
  width: 180px;
  z-index: 10;
  display: ${(props) => (props.open ? "block" : "none")};
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.35);
  overflow: hidden;
`;

const DropDownItem = styled.div`
  padding: 10px 12px;
  cursor: pointer;
  transition: all 0.2s ease;

  &:hover {
    background-color: #ff416c;
    color: #fff;
  }
`;

const Input = styled.input`
  padding: 12px 16px;
  font-size: 16px;
  border: none;
  border-radius: 12px;
  width: 220px;
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.15);
  transition: all 0.3s ease;

  &:focus {
    outline: none;
    transform: translateY(-2px);
    box-shadow: 0 8px 25px rgba(0, 0, 0, 0.25);
  }
`;

const InputWrapper = styled.div`
  position: relative;
`;

const SuggestionBox = styled.div`
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  width: 100%;
  background: ${(props) => (props.dark ? "#ffffff" : "#1f1f1f")};
  border-radius: 12px;
  z-index: 20;
  max-height: 280px;
  overflow-y: auto;
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.25);
`;

const SuggestionItem = styled.div`
  padding: 10px 14px;
  cursor: pointer;
  color: ${(props) => (props.dark ? "#121212" : "#ffffff")};

  &:hover {
    background: #ff416c;
    color: #ffffff;
  }
`;

const Button = styled.button`
  padding: 12px 22px;
  background: linear-gradient(135deg, #ff416c, #ff4b2b);
  color: #fff;
  border: none;
  border-radius: 12px;
  cursor: pointer;
  font-size: 16px;
  font-weight: 600;
  box-shadow: 0 6px 20px rgba(255, 65, 108, 0.5);
  transition: all 0.3s ease;

  &:hover {
    transform: translateY(-2px);
    box-shadow: 0 12px 30px rgba(255, 65, 108, 0.6);
  }
`;

const ButtonWrapper = styled.div`
  margin-top: 8px;
  display: flex;
  justify-content: center;
`;

const PagePagination = styled.div`
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-top: 20px;
`;

const PaginationButton = styled(Button)`
  padding: 8px 14px;
  border-radius: 50%;
  font-weight: bold;

  &:disabled {
    opacity: 0.4;
    cursor: default;
    transform: none;
    box-shadow: none;
  }
`;

const LiveSearchInput = memo(
  ({ criteria, inputValue, setInputValue, suggestions, showSuggestions, setShowSuggestions, handleSearch, handleLiveSearch, darkMode, typingTimeout }) => {
    const handleChange = (e) => {
      const value = e.target.value;
      setInputValue(value);
      if (typingTimeout.current) clearTimeout(typingTimeout.current);
      typingTimeout.current = setTimeout(() => handleLiveSearch(value), 500);
    };

    return (
      <InputWrapper>
        <Input
          type="text"
          value={inputValue}
          onChange={handleChange}
          onFocus={() => suggestions.length && setShowSuggestions(true)}
          placeholder={`Enter ${criteria}`}
          onBlur={() => setTimeout(() => setShowSuggestions(false), 150)}
        />
        {showSuggestions && suggestions.length > 0 && (
          <SuggestionBox dark={darkMode}>
            {suggestions.map((book) => (
              <SuggestionItem
                dark={darkMode}
                key={book.isbn}
                onClick={() => {
                  setInputValue(book.title);
                  setShowSuggestions(false);
                  handleSearch();
                }}
              >
                {book.title}
              </SuggestionItem>
            ))}
          </SuggestionBox>
        )}
      </InputWrapper>
    );
  }
);

const AddBook = () => {
  const { darkMode } = useContext(ThemeContext);

  const [criteria, setCriteria] = useState("Title");
  const [inputValue, setInputValue] = useState("");
  const [sort, setSort] = useState("Relevance");
  const [books, setBooks] = useState([]);
  const [searchDropDownOpen, setSearchDropDownOpen] = useState(false);
  const [sortDropDownOpen, setSortDropDownOpen] = useState(false);
  const [suggestions, setSuggestions] = useState([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const typingTimeout = useRef(null);
  const [page, setPage] = useState(1);
  const [addedBooks, setAddedBooks] = useState({});
  const [loading, setLoading] = useState(false);
  const lastRequestId = useRef(0);

  useEffect(() => {
    return () => {
      if (typingTimeout.current) clearTimeout(typingTimeout.current);
    };
  }, []);

  const pageSize = 24;
  const totalPages = Math.ceil(books.length / pageSize);

  const fetchSuggestions = useCallback(async (criteria, value) => {
    const res = await fetchQuery(null, criteria, value, "Relevance");
    return res?.slice(0, 6) || [];
  }, []);

  const handleSearch = useCallback(async (e) => {
    e?.preventDefault();
    if (!inputValue.trim()) return;
    setBooks([]);
    setLoading(true);
    const result = await fetchQuery(null, criteria, inputValue, sort);
    setShowSuggestions(false);
    setSuggestions([]);
    setBooks(result || []);
    setPage(1);
    setLoading(false);
  }, [criteria, inputValue, sort]);

  const handleLiveSearch = useCallback(async (value) => {
    if (!value.trim()) {
      setSuggestions([]);
      setShowSuggestions(false);
      return;
    }
    const requestId = ++lastRequestId.current;
    const result = await fetchSuggestions(criteria, value);
    if (requestId !== lastRequestId.current) return;
    setSuggestions(result);
    setShowSuggestions(true);
  }, [criteria, fetchSuggestions]);

  const addtoLib = useCallback((book) => {
    if (addedBooks[book.title]) return;
    setAddedBooks((prev) => ({ ...prev, [book.title]: true }));
    let myBooks = JSON.parse(localStorage.getItem("books")) || {};
    myBooks[book.title] = book;
    localStorage.setItem("books", JSON.stringify(myBooks));
  }, [addedBooks]);

  const toggleSearchDropDown = useCallback(() => {
    setSearchDropDownOpen((prev) => !prev);
    setSortDropDownOpen(false);
  }, []);

  const toggleSortDropDown = useCallback(() => {
    setSortDropDownOpen((prev) => !prev);
    setSearchDropDownOpen(false);
  }, []);

  const handleSearchDropDownItemClick = useCallback((newCriteria) => {
    setCriteria(newCriteria);
    setSearchDropDownOpen(false);
  }, []);

  const handleSortDropDownItemClick = useCallback((newSort) => {
    setSort(newSort);
    setSortDropDownOpen(false);
  }, []);

  const BookCardWithImageLoading = (props) => {
    const ImageWithLoading = withImageLoading(({ src, alt }) => (
      <img src={src} alt={alt} style={{ width: "100%", height: "auto" }} />
    ));
    return <BookCard {...props} ImageComponent={ImageWithLoading} />;
  };

  const BookGridWithLoading = withLoadingAnimation(BookGrid);

  return (
    <PageWrapper>
      <Container>
        <Heading>Discover Your Next Favorite Book</Heading>

        <SearchWrapper onSubmit={handleSearch}>
          <DropDownWrapper>
            <DropDownButton type="button" onClick={toggleSearchDropDown}>
              Search By: {criteria}
            </DropDownButton>
            <DropDownContent open={searchDropDownOpen}>
              {["Title", "Author", "ISBN"].map((item) => (
                <DropDownItem key={item} onClick={() => handleSearchDropDownItemClick(item)}>
                  {item}
                </DropDownItem>
              ))}
            </DropDownContent>
          </DropDownWrapper>

          <DropDownWrapper>
            <DropDownButton type="button" onClick={toggleSortDropDown}>
              Sort By: {sort}
            </DropDownButton>
            <DropDownContent open={sortDropDownOpen}>
              {["Relevance", "Newest", "Rating"].map((item) => (
                <DropDownItem key={item} onClick={() => handleSortDropDownItemClick(item)}>
                  {item}
                </DropDownItem>
              ))}
            </DropDownContent>
          </DropDownWrapper>

          <LiveSearchInput
            criteria={criteria}
            inputValue={inputValue}
            setInputValue={setInputValue}
            suggestions={suggestions}
            showSuggestions={showSuggestions}
            setShowSuggestions={setShowSuggestions}
            handleSearch={handleSearch}
            handleLiveSearch={handleLiveSearch}
            darkMode={darkMode}
            typingTimeout={typingTimeout}
          />

          <Button type="submit">Search</Button>
        </SearchWrapper>

        <BookGridWithLoading loading={loading}>
          {books.length > 0 &&
            books.slice((page - 1) * pageSize, page * pageSize).map((book) => (
              <div key={book.isbn}>
                <BookCardWithImageLoading {...book} />
                <ButtonWrapper>
                  <CardButton type="button" variant="add" onClick={() => addtoLib(book)}>
                    {addedBooks[book.title] ? "Added! Enjoy Reading!" : "Add to Library"}
                  </CardButton>
                </ButtonWrapper>
              </div>
            ))}
        </BookGridWithLoading>

        {books.length > 0 && totalPages > 1 && (
          <PagePagination>
            {page > 1 && (
              <PaginationButton type="button" onClick={() => setPage(page - 1)}>
                {"<"}
              </PaginationButton>
            )}
            {Array.from({ length: totalPages }, (_, index) => (
              <PaginationButton
                key={index}
                onClick={() => setPage(index + 1)}
                disabled={page === index + 1}
              >
                {index + 1}
              </PaginationButton>
            ))}
            {page < totalPages && (
              <PaginationButton type="button" onClick={() => setPage(page + 1)}>
                {">"}
              </PaginationButton>
            )}
          </PagePagination>
        )}
      </Container>
    </PageWrapper>
  );
};

export default AddBook;
